import SwiftUI
struct AboutView:View{@Environment(\.dismiss)var dismiss;static var versionText:String{let info=Bundle.main.infoDictionary;let v=info?["CFBundleShortVersionString"] as? String ?? "unknown";let b=info?["CFBundleVersion"] as? String;return b==nil||b==v ? "Version \(v)" : "Version \(v) (build \(b!))"};var body:some View{VStack(spacing:14){AppIconView().frame(width:112,height:112);Text("Blueprint Conversion Utility").font(.largeTitle.bold());Text(Self.versionText);Text("Created by Jarred Wheeler");Button("Done"){dismiss()}}.padding().frame(width:460,height:390)}}
